const body = $json.body || {};
const payload = body.payload || {};
let score = 0;
if (payload.email) score += 40;
if (payload.company) score += 30;
if (payload.source) score += 10;
if (String(payload.intent || '').toLowerCase() === 'high') score += 20;
return [{ json: { runId: body.runId, workflow: body.workflow || 'Lead qualification', event: body.event, score, qualified: score >= 50, receivedAt: new Date().toISOString() } }];
